{"actions":[{"tool":"write_file","path":"src/parcelkit/money.py","content":""""Money conversion helpers.

Amounts are handled with exact decimal arithmetic only; binary floats are
rejected so that no float ever participates in a money computation.
"""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_CENT = Decimal("0.01")


def money_minor(amount):
    """Convert ``amount`` to an integer number of minor units (cents).

    Accepts a decimal string, an ``int`` or a ``Decimal``.  Values are rounded
    to the nearest cent using half-up rounding (the project money convention),
    which is applied symmetrically to negative amounts.  ``bool`` values,
    binary floats, NaN and infinities are rejected.
    """
    if isinstance(amount, bool):
        raise TypeError("bool is not a valid money amount")
    if isinstance(amount, float):
        raise TypeError("binary float is not allowed for money amounts")

    if isinstance(amount, Decimal):
        value = amount
    elif isinstance(amount, int):
        value = Decimal(amount)
    elif isinstance(amount, str):
        text = amount.strip()
        if not text:
            raise ValueError("empty money amount")
        try:
            value = Decimal(text)
        except InvalidOperation:
            raise ValueError("invalid money amount: %r" % (amount,)) from None
    else:
        raise TypeError(
            "money amount must be str, int or Decimal, not %s"
            % type(amount).__name__
        )

    if not value.is_finite():
        raise ValueError("money amount must be finite")

    rounded = value.quantize(_CENT, rounding=ROUND_HALF_UP)
    return int(rounded.scaleb(2))
"}]}

