{"actions":[{"tool":"write_file","path":"src/parcelkit/timestamps.py","content":"from datetime import datetime, timezone


def utc_stamp(value):
    """Convert an ISO-8601 datetime string to a UTC second-precision stamp.

    Accepts strings containing a ``T`` separator. An explicit offset (or ``Z``)
    is converted to UTC. When no offset is present, the value is assumed to be
    UTC; the host local timezone is never consulted. Date-only strings, non-str
    inputs, and malformed values raise ``ValueError``.
    """
    if not isinstance(value, str):
        raise ValueError("value must be an ISO-8601 datetime string")

    text = value.strip()
    if "T" not in text:
        raise ValueError("value must contain a 'T' datetime separator")

    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ValueError("invalid ISO-8601 datetime: %r" % (value,)) from exc

    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    else:
        parsed = parsed.astimezone(timezone.utc)

    return parsed.strftime("%Y-%m-%dT%H:%M:%SZ")
"}]}

