from datetime import datetime, timezone


def utc_stamp(value):
    """Convert an ISO-8601 datetime string to a UTC second-precision stamp.

    Accepts strings containing a ``T`` separator. Explicit offsets are
    converted to UTC; naive values are assumed to be UTC per project policy.
    The result always ends with ``Z`` and has second precision.
    """
    if not isinstance(value, str):
        raise ValueError("value must be a string")
    text = value.strip()
    if "T" not in text:
        raise ValueError("value must be an ISO-8601 datetime with a T separator")
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        raise ValueError("invalid ISO-8601 datetime") from None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    else:
        parsed = parsed.astimezone(timezone.utc)
    return parsed.strftime("%Y-%m-%dT%H:%M:%SZ")

