from datetime import datetime, timezone


def utc_stamp(value):
    """Convert an ISO-8601 datetime string to a UTC second-precision stamp.

    Accepts strings containing a ``T`` separator. Explicit offsets are
    converted to UTC; naive values are assumed to be UTC (project policy),
    never the host local timezone. Returns ``YYYY-MM-DDTHH:MM:SSZ``.
    """
    if not isinstance(value, str):
        raise ValueError("value must be a string")
    if "T" not in value:
        raise ValueError("value must be an ISO-8601 datetime with 'T'")
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("invalid ISO-8601 datetime: %r" % (value,)) from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    else:
        parsed = parsed.astimezone(timezone.utc)
    return parsed.strftime("%Y-%m-%dT%H:%M:%SZ")

